package com.nanum.investment.domain;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="\"TB_EXCH_DAY\"",uniqueConstraints=@UniqueConstraint(name="UK_TB_EXCH_DAY_01",columnNames={"BASE_DT","BASE_CURR_CD","QUOTE_CURR_CD"})) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class TbExchDay { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="EXCH_DAY_ID") private Long exchangeDayId; @Column(name="BASE_DT",nullable=false) private LocalDate baseDate; @Column(name="BASE_CURR_CD",nullable=false,length=10) private String baseCurrencyCode; @Column(name="QUOTE_CURR_CD",nullable=false,length=10) private String quoteCurrencyCode; @Column(name="EXCH_RT",nullable=false,precision=20,scale=6) private BigDecimal exchangeRate; @Column(name="PREV_EXCH_RT",precision=20,scale=6) private BigDecimal previousExchangeRate; @Column(name="CHG_RT",precision=10,scale=4) private BigDecimal changeRate; @Column(name="DATA_SRC_CD",nullable=false,length=30) private String dataSourceCode; @Enumerated(EnumType.STRING) @Builder.Default @Column(name="DATA_STS",nullable=false,length=20) private DataStatus dataStatus=DataStatus.FRESH; }
